using System;using System.IO;using UnityEngine;using UnityEditor;using Racer;
public static class ImportPermanentNetwork {
 public static string Main(){const string path="Assets/Resources/WorldMaps/PermanentWorld.png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Default;importer.maxTextureSize=8192;importer.npotScale=TextureImporterNPOTScale.None;importer.mipmapEnabled=false;importer.isReadable=true;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.filterMode=FilterMode.Bilinear;importer.wrapMode=TextureWrapMode.Clamp;importer.SaveAndReimport();var m=AssetDatabase.LoadAssetAtPath<WorldMapVisual>("Assets/Resources/WorldMaps/PermanentWorld.asset");if(!m){m=ScriptableObject.CreateInstance<WorldMapVisual>();AssetDatabase.CreateAsset(m,"Assets/Resources/WorldMaps/PermanentWorld.asset");}m.bounds=new Rect(-1350,-850,3000,1800);m.sourceScene="Registered Forest / Backyard / Mountain composite + exported permanent network";m.image=AssetDatabase.LoadAssetAtPath<Texture2D>(path);EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();return "Shared permanent menu world imported";}
}
